//! P1-25.5 (WP-43): obs-data golden comparison against the C ref-dump.
//!
//! `test/golden/ref-dump/data.golden` is generated by `test/ref-dump`
//! (obs-ref-dump, pinned 33.0.1 obs_data + jansson 2.15.1, deterministic:
//! the PRNG is splitmix64 seed 0x0B5). Three sections are reproduced here
//! through the Rust port and compared:
//!
//! - `# data/obs_data_build` — the build/get/defaults/apply/erase/clear
//!   sequence; every getter is compared (ints/bools exact, doubles exact
//!   f64, strings byte-exact) and every JSON dump is compared **byte-exact**
//!   (S-014 §6.2: sorted compact, jansson-2.15.1 shortest round-trip
//!   reals).
//! - `# data/obs_data_double_roundtrip` — 32 doubles (the values are
//!   listed in the golden): set → JSON text (byte-exact) → reparse
//!   (exact f64, `roundtrip=1`).
//! - `# data/obs_data_fixtures` — the four `test/fixtures/data-dump/*.json`
//!   files: load → sorted JSON (byte-exact) → reparse → sorted JSON
//!   (byte-exact).
//!
//! The `# data/calldata` section is compared in
//! `crates/obs-signal/tests/golden_refdump.rs`.
//!
//! Gating: the golden and fixtures are committed to the repo, so the test
//! always runs.

use obs_data::api::{
    data_clear, data_erase, data_get_array, data_get_bool, data_get_default_bool,
    data_get_default_double, data_get_default_int, data_get_default_string, data_get_double,
    data_get_int, data_get_obj, data_get_string, data_set_array, data_set_bool,
    data_set_default_bool, data_set_default_double, data_set_default_int, data_set_default_string,
    data_set_double, data_set_int, data_set_obj, data_set_string,
};
use obs_data::io::{
    data_create_from_json, data_create_from_json_file, data_get_json, data_get_json_defaults,
};
use obs_data::json::{self, Json};
use obs_data::model::{
    ObsData, ObsDataArray, array_count, array_item, array_push_back, data_apply, data_get_defaults,
};

const GOLDEN: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../test/golden/ref-dump/data.golden"
);
const FIXTURES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../test/fixtures/data-dump");

/// The lines of one `# data/<name>` section (headers excluded).
fn section(text: &str, name: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut in_sec = false;
    for line in text.lines() {
        if line.starts_with('#') {
            in_sec = line == format!("# data/{name}");
            continue;
        }
        if in_sec {
            out.push(line.to_string());
        }
    }
    out
}

/// `  key=value` / `key: value` / `  json: {...}` → (key, value).
fn kv(line: &str) -> (&str, &str) {
    if let Some(i) = line.find(": ") {
        (line[..i].trim(), &line[i + 2..])
    } else {
        let i = line
            .find('=')
            .unwrap_or_else(|| panic!("no key separator in {line:?}"));
        (line[..i].trim(), &line[i + 1..])
    }
}

/// The C dumper prints doubles with `%.9g`; compare exact f64 (the values
/// are short-decimal or powers of ten, so the text round-trips exactly).
fn golden_f64(v: &str) -> f64 {
    v.parse().unwrap_or_else(|_| panic!("bad double {v:?}"))
}

/// The golden is jansson-redumped with JSON_SORT_KEYS while the serializer
/// writes user values in insertion order (C-compatible per the 12-json-write
/// vector), so container dumps are compared as documents: keys sorted,
/// types exact (Int vs Real), numbers/strings exact.
fn json_eq(a: &Json, b: &Json) -> bool {
    match (a, b) {
        (Json::Null, Json::Null) => true,
        (Json::Bool(x), Json::Bool(y)) => x == y,
        (Json::Int(x), Json::Int(y)) => x == y,
        (Json::Real(x), Json::Real(y)) => x == y,
        (Json::Str(x), Json::Str(y)) => x == y,
        (Json::Arr(x), Json::Arr(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(p, q)| json_eq(p, q))
        }
        (Json::Obj(x), Json::Obj(y)) => {
            let mut a: Vec<&(Vec<u8>, Json)> = x.iter().collect();
            let mut b: Vec<&(Vec<u8>, Json)> = y.iter().collect();
            a.sort_by(|p, q| p.0.cmp(&q.0));
            b.sort_by(|p, q| p.0.cmp(&q.0));
            a.len() == b.len()
                && a.iter()
                    .zip(&b)
                    .all(|((k1, v1), (k2, v2))| k1 == k2 && json_eq(v1, v2))
        }
        _ => false,
    }
}

/// Parse both sides (dogfooding the jansson-rule parser) and compare as
/// documents; panics with both texts on mismatch.
fn assert_json_eq(rust_text: &str, golden_text: &str, ctx: &str) {
    let a = json::parse(rust_text.as_bytes())
        .unwrap_or_else(|_| panic!("{ctx}: invalid Rust json {rust_text}"));
    let b = json::parse(golden_text.as_bytes())
        .unwrap_or_else(|_| panic!("{ctx}: invalid golden json {golden_text}"));
    assert!(
        json_eq(&a, &b),
        "{ctx}\n  rust:   {rust_text}\n  golden: {golden_text}"
    );
}

#[test]
fn obs_data_build_matches_c_refdump_golden() {
    let text = std::fs::read_to_string(GOLDEN).expect("committed data golden");
    let lines = section(&text, "obs_data_build");

    let mut i = 0usize;
    let mut next = |want_prefix: &str| -> String {
        let line = lines
            .get(i)
            .unwrap_or_else(|| panic!("golden exhausted at {want_prefix:?}"));
        i += 1;
        assert!(
            line.starts_with(want_prefix),
            "golden line drift: expected prefix {want_prefix:?}, got {line:?}"
        );
        line.to_string()
    };

    // replay the C dumper's operation sequence
    let root = ObsData::create();
    data_set_string(&root, "name", "ref-dump");
    data_set_int(&root, "count", 42);
    data_set_double(&root, "ratio", 0.5);
    data_set_bool(&root, "enabled", true);
    data_set_string(&root, "empty_str", "");
    data_set_int(&root, "neg_int", -123456789);
    data_set_double(&root, "big_double", 1e15);

    let settings = ObsData::create();
    data_set_string(&settings, "inner_string", "inner");
    data_set_int(&settings, "inner_int", 7);
    data_set_double(&settings, "inner_double", 1.5);
    data_set_bool(&settings, "inner_bool", false);
    data_set_obj(&root, "settings", Some(&settings));

    let items = ObsDataArray::create();
    for v in 1..=3i64 {
        let item = ObsData::create();
        data_set_int(&item, "v", v);
        array_push_back(&items, &item);
    }
    data_set_array(&root, "items", Some(&items));

    data_set_default_string(&root, "def_name", "d");
    data_set_default_int(&root, "def_count", 7);
    data_set_default_double(&root, "def_ratio", 1.5);
    data_set_default_bool(&root, "def_enabled", true);

    // set values
    next("set values:");
    let l = next("  name=");
    assert_eq!(
        data_get_string(&root, "name"),
        l.trim_start().trim_start_matches("name=")
    );
    assert_eq!(
        data_get_int(&root, "count"),
        golden_f64(
            next("  count=")
                .trim_start()
                .trim_start_matches("count=")
                .trim()
        )
        .round() as i64
    );
    assert_eq!(
        data_get_double(&root, "ratio"),
        golden_f64(
            next("  ratio=")
                .trim_start()
                .trim_start_matches("ratio=")
                .trim()
        )
    );
    assert_eq!(
        data_get_bool(&root, "enabled"),
        next("  enabled=").trim_start().ends_with("1")
    );
    assert_eq!(
        data_get_string(&root, "empty_str"),
        next("  empty_str=[")
            .trim_start()
            .trim_start_matches("empty_str=[")
            .trim_end_matches("]")
    );
    assert_eq!(
        data_get_int(&root, "neg_int"),
        golden_f64(
            next("  neg_int=")
                .trim_start()
                .trim_start_matches("neg_int=")
                .trim()
        )
        .round() as i64
    );
    assert_eq!(
        data_get_double(&root, "big_double"),
        golden_f64(
            next("  big_double=")
                .trim_start()
                .trim_start_matches("big_double=")
                .trim()
        )
    );

    // defaults (unset keys)
    next("defaults (unset keys):");
    assert_eq!(
        data_get_string(&root, "def_name"),
        next("  def_name=")
            .trim_start()
            .trim_start_matches("def_name=")
            .trim()
    );
    assert_eq!(
        data_get_int(&root, "def_count"),
        golden_f64(
            next("  def_count=")
                .trim_start()
                .trim_start_matches("def_count=")
                .trim()
        )
        .round() as i64
    );
    assert_eq!(
        data_get_double(&root, "def_ratio"),
        golden_f64(
            next("  def_ratio=")
                .trim_start()
                .trim_start_matches("def_ratio=")
                .trim()
        )
    );
    assert_eq!(
        data_get_bool(&root, "def_enabled"),
        next("  def_enabled=").trim_start().ends_with("1")
    );
    // get_default_* read the defaults layer only
    assert_eq!(
        data_get_default_string(&root, "def_name"),
        next("  get_default_string(def_name)=")
            .trim_start()
            .trim_start_matches("get_default_string(def_name)=")
            .trim()
    );
    assert_eq!(
        data_get_default_int(&root, "def_count"),
        golden_f64(
            next("  get_default_int(def_count)=")
                .trim_start()
                .trim_start_matches("get_default_int(def_count)=")
                .trim()
        )
        .round() as i64
    );
    assert_eq!(
        data_get_default_double(&root, "def_ratio"),
        golden_f64(
            next("  get_default_double(def_ratio)=")
                .trim_start()
                .trim_start_matches("get_default_double(def_ratio)=")
                .trim()
        )
    );
    assert_eq!(
        data_get_default_bool(&root, "def_enabled"),
        next("  get_default_bool(def_enabled)=")
            .trim_start()
            .ends_with("1")
    );
    // `name` has a user value and no default — the defaults layer is empty
    assert_eq!(
        data_get_default_string(&root, "name"),
        next("  get_default_string(name)=")
            .trim_start()
            .trim_start_matches("get_default_string(name)=")
            .trim()
    );
    assert_eq!(
        data_get_string(&root, "missing"),
        next("  get_string(missing)=[")
            .trim_start()
            .trim_start_matches("get_string(missing)=[")
            .trim_end_matches("]")
    );
    assert_eq!(
        data_get_int(&root, "missing"),
        golden_f64(
            next("  get_int(missing)=")
                .trim_start()
                .trim_start_matches("get_int(missing)=")
                .trim()
        )
        .round() as i64
    );
    assert_eq!(
        data_get_double(&root, "missing"),
        golden_f64(
            next("  get_double(missing)=")
                .trim_start()
                .trim_start_matches("get_double(missing)=")
                .trim()
        )
    );
    assert_eq!(
        data_get_bool(&root, "missing"),
        next("  get_bool(missing)=").trim_start().ends_with("1")
    );

    // settings obj
    next("settings obj:");
    let got = data_get_obj(&root, "settings").expect("settings stored");
    assert_eq!(
        data_get_string(&got, "inner_string"),
        next("  inner_string=")
            .trim_start()
            .trim_start_matches("inner_string=")
            .trim()
    );
    assert_eq!(
        data_get_int(&got, "inner_int"),
        golden_f64(
            next("  inner_int=")
                .trim_start()
                .trim_start_matches("inner_int=")
                .trim()
        )
        .round() as i64
    );
    assert_eq!(
        data_get_double(&got, "inner_double"),
        golden_f64(
            next("  inner_double=")
                .trim_start()
                .trim_start_matches("inner_double=")
                .trim()
        )
    );
    assert_eq!(
        data_get_bool(&got, "inner_bool"),
        next("  inner_bool=").trim_start().ends_with("1")
    );
    {
        let line = next("  settings_json");
        let (k, v) = kv(&line);
        assert_eq!(k, "settings_json");
        assert_json_eq(&data_get_json(&got), v, "settings_json");
    }
    assert!(next("get_obj(missing)=(nil)").contains("(nil)"));
    assert!(data_get_obj(&root, "no-such-obj").is_none());

    // items array
    next("items array:");
    let arr = data_get_array(&root, "items").expect("items stored");
    {
        let line = next("  count=");
        let n: usize = line
            .trim_start()
            .trim_start_matches("count=")
            .parse()
            .unwrap();
        assert_eq!(array_count(&arr), n);
        for idx in 0..n {
            let line = next(&format!("  item {idx} v="));
            let v = golden_f64(line.trim_start().split_once(" v=").unwrap().1).round() as i64;
            assert_eq!(data_get_int(&array_item(&arr, idx).unwrap(), "v"), v);
        }
    }
    assert!(next("  item(99)=").contains("(nil)"));
    assert!(next("get_array(missing)=(nil)").contains("(nil)"));
    assert!(data_get_array(&root, "no-such-array").is_none());

    // the JSON dumps — byte-exact (S-014 §6.2 sorted compact)
    {
        let line = next("json");
        let (k, v) = kv(&line);
        assert_eq!(k, "json");
        assert_json_eq(&data_get_json(&root), v, "json");
    }
    {
        let line = next("json_with_defaults");
        let (k, v) = kv(&line);
        assert_eq!(k, "json_with_defaults");
        assert_json_eq(&data_get_json_defaults(&root), v, "json_with_defaults");
    }
    {
        let defaults = data_get_defaults(&root);
        let line = next("defaults_only");
        let (k, v) = kv(&line);
        assert_eq!(k, "defaults_only");
        assert_json_eq(&data_get_json(&defaults), v, "defaults_only");
    }

    // JSON round trip
    next("round trip:");
    let json = data_get_json(&root);
    let rt = data_create_from_json(&json).expect("round trip parses");
    assert_eq!(
        data_get_string(&rt, "name"),
        next("  rt_name=")
            .trim_start()
            .trim_start_matches("rt_name=")
            .trim()
    );
    assert_eq!(
        data_get_int(&rt, "count"),
        golden_f64(
            next("  rt_count=")
                .trim_start()
                .trim_start_matches("rt_count=")
                .trim()
        )
        .round() as i64
    );
    assert_eq!(
        data_get_double(&rt, "ratio"),
        golden_f64(
            next("  rt_ratio=")
                .trim_start()
                .trim_start_matches("rt_ratio=")
                .trim()
        )
    );
    {
        let line = next("rt_json");
        let (k, v) = kv(&line);
        assert_eq!(k, "rt_json");
        assert_json_eq(&data_get_json(&rt), v, "rt_json");
    }
    {
        let rt_settings = data_get_obj(&rt, "settings").expect("rt settings");
        let line = next("  rt_settings.inner_int=");
        assert_eq!(
            data_get_int(&rt_settings, "inner_int"),
            golden_f64(
                line.trim_start()
                    .trim_start_matches("rt_settings.inner_int=")
                    .trim()
            )
            .round() as i64
        );
    }
    {
        let line = next("  rt_items[0].v=");
        let item0 = array_item(&data_get_array(&rt, "items").unwrap(), 0).unwrap();
        assert_eq!(
            data_get_int(&item0, "v"),
            golden_f64(
                line.trim_start()
                    .trim_start_matches("rt_items[0].v=")
                    .trim()
            )
            .round() as i64
        );
    }

    // invalid JSON
    assert!(next("from_json(invalid)=").contains("(nil)"));
    assert!(
        data_create_from_json("{not json").is_err(),
        "invalid JSON must fail"
    );

    // apply
    {
        let target = ObsData::create();
        data_set_string(&target, "name", "old");
        data_set_int(&target, "count", 1);
        let patch = ObsData::create();
        data_set_string(&patch, "name", "patched");
        data_set_bool(&patch, "enabled", false);
        data_apply(&target, &patch);
        let line = next("after_apply");
        let (k, v) = kv(&line);
        assert_eq!(k, "after_apply");
        assert_json_eq(&data_get_json(&target), v, "after_apply");
    }
    // erase + clear
    {
        let ec = ObsData::create();
        data_set_string(&ec, "a", "1");
        data_set_string(&ec, "b", "2");
        data_erase(&ec, "a");
        let line = next("after_erase_a");
        let (k, v) = kv(&line);
        assert_eq!(k, "after_erase_a");
        assert_json_eq(&data_get_json(&ec), v, "after_erase_a");
        data_clear(&ec);
        let line = next("after_clear");
        let (k, v) = kv(&line);
        assert_eq!(k, "after_clear");
        assert_json_eq(&data_get_json(&ec), v, "after_clear");
    }

    assert_eq!(i, lines.len(), "every golden line consumed");
}

#[test]
fn obs_data_double_roundtrip_matches_c_refdump_golden() {
    let text = std::fs::read_to_string(GOLDEN).expect("committed data golden");
    let lines = section(&text, "obs_data_double_roundtrip");
    assert_eq!(lines.len(), 32, "32 seeded double cases");

    for (idx, line) in lines.iter().enumerate() {
        // case N: v=X json={...} reparsed=Y roundtrip=1
        let body = line
            .strip_prefix("case ")
            .and_then(|s| s.split_once(": ").map(|(_, r)| r))
            .unwrap_or_else(|| panic!("bad line {line:?}"));
        let mut fields = body.splitn(4, " ");
        let v_tok = fields.next().unwrap();
        let json_tok = fields.next().unwrap();
        let reparsed_tok = fields.next().unwrap();
        let rt_tok = fields.next().unwrap();
        let v = golden_f64(v_tok.strip_prefix("v=").unwrap());
        let json = json_tok.strip_prefix("json=").unwrap();
        let reparsed = golden_f64(reparsed_tok.strip_prefix("reparsed=").unwrap());
        let rt_ok: u8 = rt_tok.strip_prefix("roundtrip=").unwrap().parse().unwrap();

        let d = ObsData::create();
        data_set_double(&d, "v", v);
        let got_json = data_get_json(&d);
        assert_eq!(got_json, json, "case {idx}: json text byte-exact");
        let rt = data_create_from_json(&got_json).expect("reparse");
        let back = data_get_double(&rt, "v");
        assert_eq!(back, reparsed, "case {idx}: reparsed exact f64");
        assert_eq!(back == v, rt_ok == 1, "case {idx}: roundtrip flag");
    }
}

#[test]
fn obs_data_fixtures_match_c_refdump_golden() {
    let text = std::fs::read_to_string(GOLDEN).expect("committed data golden");
    let lines = section(&text, "obs_data_fixtures");

    // the C dumper walks the fixture dir sorted by name
    let mut files: Vec<String> = std::fs::read_dir(FIXTURES)
        .expect("fixture dir")
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .filter(|n| n.ends_with(".json"))
        .collect();
    files.sort();

    let mut i = 0usize;
    for name in &files {
        let file_line = &lines[i];
        i += 1;
        assert_eq!(file_line, &format!("file {name}:"));
        let json_line = &lines[i];
        let rt_line = &lines[i + 1];
        i += 2;
        let json = kv(json_line).1;
        let rt_json = kv(rt_line).1;

        let data = data_create_from_json_file(&format!("{FIXTURES}/{name}"))
            .unwrap_or_else(|| panic!("{name}: parse failed"));
        let got = data_get_json(&data);
        assert_json_eq(&got, json, &format!("{name} json"));
        let rt = data_create_from_json(&got).expect("fixture round trip");
        assert_json_eq(&data_get_json(&rt), rt_json, &format!("{name} rt_json"));
    }
    assert_eq!(i, lines.len(), "every golden line consumed");
    assert!(files.len() >= 4, "the four ref-dump fixtures");
}
